 "content": "def transform(grid):
    """Overlay the four equal-height color masks using fixed color precedence."""
    h = len(grid)
    if h % 4:
        raise ValueError("expected four equal-height layers")
    layer_h = h // 4
    width = len(grid[0])
    # When masks overlap, foreground precedence is 5, then 4, then 8, then 2.
    precedence = (5, 4, 8, 2)
    out = [[0] * width for _ in range(layer_h)]
    for r in range(layer_h):
        for c in range(width):
            colors = {grid[layer * layer_h + r][c] for layer in range(4)}
            for color in precedence:
                if color in colors:
                    out[r][c] = color
                    break
    return out
